    assertThat(response.checkedInAt()).isEqualTo(arrived);
    assertThat(response.recordedBy()).isEqualTo("ops");
    assertThat(response.checkpointName()).isEqualTo("Sankri");
    verify(checkInRepository).saveAndFlush(any(CheckIn.class));
  }

